// Shadertoy GLSL Shader: Tunnel Effect Through Space


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;  // Normalized pixel coordinates (0 to 1)
    uv = uv * 2.0 - 1.0;  // Center coordinates to range from -1 to 1
    uv.x *= iResolution.x / iResolution.y;  // Correct aspect ratio

    float time = iTime * 0.1; // Control the speed of the tunnel effect

    // Create a radial tunnel effect
    float angle = atan(uv.y, uv.x); // Angle for the radial effect
    float radius = length(uv); // Radius from the center of the screen

    // Create a repeating texture effect for the tunnel walls
    float tunnelPattern = cos(17.0 * radius - time * -10.0); 
    float tunnelDepth = 10.0 / (radius + 0.4); // Depth effect, makes tunnel appear pulled backward

    // Simulate stars or particles being pulled backward
    vec2 starPos = vec2(mod(time + angle, 1.0), mod(time + radius * -100.0, 10.0));
    float starBrightness = smoothstep(0.0, 10.9, fract(sin(dot(starPos, vec2(0.9898, 0.233))) * 10.5453));

    // Lighting effect to simulate light along the tunnel walls
    vec3 lightColor = vec3(0.02, 0.09, 0.2) * tunnelPattern * tunnelDepth;

    // Combine star and lighting effects for the final tunnel scene
    vec3 starColor = vec3(starBrightness);
    vec3 tunnelColor = lightColor + starColor;

    // Output the final color
    fragColor = vec4(tunnelColor, 1.0);
}

// Common.glsl

// Function to generate noise
float noise(vec2 uv) {
    return fract(sin(dot(uv.xy, vec2(12.9898, 78.233))) * 43758.5453);
}

// Lighting function
vec3 calculateLighting(vec3 normal, vec3 lightDir, vec3 lightColor) {
    float diffuse = max(dot(normal, lightDir), 0.0);
    return lightColor * diffuse;
}
